import { createHash } from "node:crypto"
import { readFileSync, writeFileSync } from "node:fs"
import stringify from "/Users/seve/Documents/Codex/2026-10-10/new-chat-3/work/tscircuit-autorouter/node_modules/fast-json-stable-stringify/index.js"
const repo = "/Users/seve/Documents/Codex/2026-10-10/new-chat-3/work/tscircuit-autorouter"
const module = await import(`${repo}/dist/index.js`)
const Pool = module.Pipeline9LocalWorkerPool
const snapshotDescriptor = Object.getOwnPropertyDescriptor(Pool.prototype, "getNativeReferenceFactStats")!
const snapshot = snapshotDescriptor.value
const input = JSON.parse(readFileSync(`${repo}/node_modules/dataset-srj18/samples/sample001.json`, "utf8"))
const solver = new module.AutoroutingPipelineSolver9_Parallel(input, {effort:1,cacheProvider:null,workerCount:4,pathingStrategy:"indexed",enableParallelDrcTrials:false,enableParallelPathSimplification:true})
let geometryHash: string
let before: Record<string,number>
try {
  await solver.solveAsync()
  if (!solver.solved || solver.failed) throw new Error(solver.error ?? "Packaged solver failed")
  geometryHash = createHash("sha256").update(stringify(solver.getOutputSimplifiedPcbTraces())!).digest("hex")
  if (geometryHash !== "a4c788251b5f5829d22c487487090a9a898a7cffee5fe96ca767440478b8c049") throw new Error("Packaged geometry mismatch")
  before = Reflect.apply(snapshot, solver.workerPool, [])
  if (before.batchesCompleted < 1 || before.workerFactRowsCompleted < 1 || before.mainFactRowsCompleted < 1 || before.protocolFaults !== 0 || before.maxFactWorkerLanes > 3 || before.mainFactLaneCount !== 1 || before.workersReserved !== before.workersRetired) throw new Error("Invalid packaged private counters")
} finally { await solver.dispose() }
const after = Reflect.apply(snapshot, solver.workerPool, [])
if (JSON.stringify(before!) !== JSON.stringify(after)) throw new Error("Disposal changed fact counts")
let reads = 0
Object.defineProperty(solver.workerPool, "getNativeReferenceFactStats", {get():never {reads++;throw new Error("observer")},configurable:true})
if (Reflect.apply(snapshot, solver.workerPool, []) !== undefined || reads !== 0) throw new Error("Snapshot observed own getter")
writeFileSync("/tmp/native-fact-packaged-001-proof.json",JSON.stringify({geometryHash:geometryHash!,before:before!,after,ownGetterReads:reads,actualBuiltPrototype:true,noSourcePrivateImports:true},null,2)+"\n")
console.log(JSON.stringify({geometryHash:geometryHash!,facts:after}))
